def _user_dir(env, fallback):
    return os.path.join(os.environ.get(env) or os.path.expanduser(fallback), APP_NAME)


DATA_DIR = _user_dir("XDG_DATA_HOME", "~/.local/share")
CACHE_DIR = _user_dir("XDG_CACHE_HOME", "~/.cache")
